using UnityEngine;using UnityEditor;using UnityEditor.Animations;using System.Linq;
public static class NereoIdleFix {public static string Run(){var c=AssetDatabase.LoadAssetAtPath<AnimatorController>("Assets/Resources/WorldProgression/NereoForge/NereoIdle.controller");var clip=AssetDatabase.LoadAllAssetsAtPath("Assets/Kevin Iglesias/Human Animations/Animations/Male/Idles/HumanM@Idle01.fbx").OfType<AnimationClip>().First(x=>!x.name.StartsWith("__"));c.layers[0].stateMachine.states[0].state.motion=clip;EditorUtility.SetDirty(c);foreach(var m in Resources.LoadAll<Material>("WorldProgression/NereoForge")){if(m.name.Contains("Paño")||m.name.Contains("Cuero")||m.name.Contains("Vendas")){var tex=Resources.Load<Texture2D>("WorldFour/Basalto estratificado-surface");m.SetTexture("_BaseMap",tex);m.SetTextureScale("_BaseMap",Vector2.one*5);EditorUtility.SetDirty(m);}}AssetDatabase.SaveAssets();return "Relaxed idle from Human Basic Motions applied";}}
